<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        &amp;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">sys-&gt;slave_speed_ctrl</span></span>
